urlset:
{%- assign sm_newest = '' -%}
{%- for sp in site.posts -%}
  {%- assign sp_lang = sp.lang | default: 'en' -%}
  {%- if sp_lang == include.sm_lang and sm_newest == '' -%}{%- assign sm_newest = sp.date | date_to_xmlschema -%}{%- endif -%}
{%- endfor -%}
{%- for pg in site.html_pages -%}
  {%- assign pg_lang = pg.lang | default: 'en' -%}
  {%- if pg.sitemap != false and pg_lang == include.sm_lang %}

    {{ pg.url | absolute_url | xml_escape }}
    {%- if pg.last_modified_at %}
    {{ pg.last_modified_at | date_to_xmlschema }}
    {%- elsif pg.url == site.data.seo_languages[pg_lang].archive_url and sm_newest != '' %}
    {{ sm_newest }}
    {%- endif %}
    {%- if pg.translation_key -%}
      {%- include page-cluster.html key=pg.translation_key -%}
      {%- if cl_members.size > 1 -%}
        {%- for m in cl_members -%}
          {%- assign m_l = site.data.seo_languages[m.lang] -%}
          {%- for code in m_l.hreflang %}

          {%- endfor -%}
        {%- endfor -%}
        {%- if cl_en %}

        {%- endif -%}
      {%- endif -%}
    {%- endif -%}
    {%- comment -%} language archive pages: the set of archive pages (same as the hreflang tags in their head) {%- endcomment -%}
    {%- if pg.url == site.data.seo_languages[pg_lang].archive_url and site.data.seo_languages[pg_lang].hreflang.size > 0 -%}
      {%- for e in site.data.seo_languages -%}
        {%- if e[1].hreflang.size > 0 -%}
          {%- for code in e[1].hreflang %}

          {%- endfor -%}
        {%- endif -%}
      {%- endfor %}

    {%- endif %}

  {%- endif -%}
{%- endfor -%}
{%- for sp in site.posts -%}
  {%- assign sp_lang = sp.lang | default: 'en' -%}
  {%- if sp_lang == include.sm_lang -%}
    {%- include title-parts.html t=sp.title -%}
    {%- if sp.last_modified_at -%}
      {%- assign sm_mod = sp.last_modified_at | date_to_xmlschema -%}
    {%- elsif title_stamp != '' -%}
      {%- assign sm_mod = title_stamp -%}
    {%- else -%}
      {%- assign sm_mod = sp.date | date_to_xmlschema -%}
    {%- endif -%}
    {%- include translation-cluster.html slug=sp.slug lang=sp_lang %}

    {{ sp.url | absolute_url | xml_escape }}
    {{ sm_mod }}
    {%- if cl_members.size > 1 -%}
      {%- for m in cl_members -%}
        {%- assign m_lang = m.lang | default: 'en' -%}
        {%- assign m_l = site.data.seo_languages[m_lang] -%}
        {%- for code in m_l.hreflang %}

        {%- endfor -%}
      {%- endfor -%}
      {%- if cl_en %}

      {%- endif -%}
    {%- endif %}

  {%- endif -%}
{%- endfor %}
